    head = observation.get('head', {})
    pos = head.get('pos', (0, 0))
    size = observation.get('size', (0, 0))
    grid = observation.get('grid', [])

    # Helper to clamp to valid moves
    def valid(dx, dy):
        return dx in (-1, 0, 1) and dy in (-1, 0, 1)

    # Basic safe strategy:
    #  - If there is a target resource or opponent in adjacent cells, move towards it.
    #  - Otherwise, bias toward center of grid to maintain control.
    x, y = pos if isinstance(pos, (list, tuple)) and len(pos) >= 2 else (0, 0)
    w, h = size if isinstance(size, (list, tuple)) and len(size) >= 2 else (0, 0)

    # Look for a nearby objective in observation fields defensively
    # Try common keys without assuming structure
    targets = []
    for key in ('resource', 'resource_positions', 'resources', 'targets', 'evader', 'opponent', 'goal'):
