            if isinstance(val, (list, tuple)) and len(val) > 0:
                for t in val:
                    if isinstance(t, (list, tuple)) and len(t) >= 2:
                        targets.append((int(t[0]), int(t[1])))
                    elif isinstance(t, dict):
