                            targets.append((int(p[0]), int(p[1])))

    # If there is a directly adjacent target, move toward it
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            tx, ty = x + dx, y + dy
            if (tx, ty) in targets:
                if valid(dx, dy):
                    return [dx, dy]

    # Otherwise prefer moving toward center to maintain map control
    cx = w // 2
    cy = h // 2
    best_dx, best_dy = 0, 0
    best_dist = None

    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if w and h:
