            if best_dist is None or dist < best_dist:
                best_dist = dist
                best_dx, best_dy = dx, dy

    # Fallback to staying in place if no move found
    if best_dx == 0 and best_dy == 0:
        return [0, 0]
    return [best_dx, best_dy]

